import numpy as np
def equation(eps, T, params):
    return (params[0] + params[1]*T)*(params[2] + eps)**(params[3] + params[4]*T)

from scipy.optimize import least_squares
forms={
 'pow_T': lambda p: p[0]*T**p[1] + p[2]*eps**p[3]*T**p[4],
 'pow_T_lin': lambda p: p[0]*T**p[1] + (p[2]+p[5]*T)*eps**p[3],
 'exp_T': lambda p: p[0]*np.exp(p[1]*T) + p[2]*eps**p[3]*np.exp(p[4]*T),
 'exp_T_log': lambda p: p[0]*np.exp(p[1]*T) + p[2]*np.log(1+p[3]*eps)*np.exp(p[4]*T)+p[5]*eps,
 'voce_pow': lambda p: p[0]*T**p[1] + p[2]*(1-np.exp(-p[3]*eps))*T**p[4],
 'swift_T': lambda p: (p[0]*T**p[1])*(p[2]+eps)**(p[3]*T**p[4]) ,
}
rng=np.random.default_rng(0)
for name,f in forms.items():
    best=None
    for trial in range(40):
        p0=rng.uniform(-2,2,6)
        if name=='swift_T': p0=rng.uniform(0.1,2,5)
        try:
            r=least_squares(lambda p: f(p)-sigma, p0, max_nfev=2000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    print(name, np.mean(best.fun**2)/np.var(sigma), np.round(best.x,4))

